if wantexit then begin
              with party do begin
                 xaxis := 20; yaxis := 8; map := 1;
              end;
              load;
              scroll(TRUE);
           end
           else begin
              if y < 25 then inc(y) else dec(y);
              scroll(TRUE);
           end

begin
      if at(15,6) then begin
         i := 100 + 20 * x1;
         j := 100 + 20 * y1;
         putimage(i,j,font^[44],CopyPut);
         putimage(i,j,chara^[24+28],AndPut);
         putimage(i,j,chara^[24],OrPut);
         Print(7,' 당신 앞의 사람이 갑자기 어떤 남자로 변하였');
         Print(7,'다.');
         PressAnyKey;
         Print(7,' 당신과는 초면이 아니지요? LORE 성에서도 봤');
         Print(7,'으니까 말이죠. 당신은 나의 정체가 어떨지 궁');
         Print(7,'금하기도 하겠지만 나중에 밝혀질 일이이까 천');
         Print(7,'천히 알아보기로 하고  먼저 이 피라밋에 대해');
         Print(7,'서 말하기로 하지요.');
         Print(7,' 이 피라밋은 Necromancer와 함께 저편의 공간');
         Print(7,'에서 퉁겨져 나왔지요. 이곳은 육신은 죽고 의');
         Print(7,'지만 남은 사람들의 안식처라고도 할수 있죠.');
         Print(7,' 여기의 ''의지''들 중에서  당신과 관계가 없는');
         Print(7,'의지는 모두 재가 되어버릴 거요. 여기서 얻은');
         Print(7,'정보는 모두 당신의 운명을 더욱 더 모질게 만');
         Print(7,'들어 버릴 것들이지만, 만약 당신이 알지 못한');
         Print(7,'다면 더더욱 더 당신을 힘겹게 하는 것들만 있');
         Print(7,'지요.  당신의 현명한 판단에 모든걸 맡기도록');
         Print(7,'하지요.');
         talk('');
         putimage(i,j,font^[52],CopyPut);
      end
      else if at(10,14) then begin
         Print(7,' 당신이 유골에 다가서자  어디선가 소리가 들');
         Print(7,'려왔다.');
         PressAnyKey;
         Print(7,' 오! 당신이 나의 잠을 깨웠나 ?');
         Print(7,' 실로 몇 천년 만에 보는 세상이군. 나는 당신');
         cPrint(7,12,'의 운명적인 만남을 관장하는 ','데네브의 의지','라');
         Print(7,'고 불리우고 있지. 당신이 만나게 될 사람들은');
         Print(7,'이미 자네가 세상에 나기 전부터  정해져 있었');
         Print(7,'다네.  만약 그 사람들을 만나지 않고  지나쳐');
         Print(7,'버린다거나 못 만나는 경우가 생긴다면 절대로');
         Print(7,'Necromancer 를 물리치지 못할걸세.  그렇다면');
         Print(7,'당신이 꼭 만나야 할 사람들을 말해 보겠네.');
         talk('');
         Print(15,' Red Antares');
         Print(7,' 그는 이미 죽은지가 수 천년이 지났지만 그의');
         Print(7,'의지는 아직 NOTICE란 동굴속에 잠들어 있네.');
         Print(7,' 그는 과거 최강의 마법사로서 이 땅을 통치하');
         Print(7,'였고 다시 세계가 혼미스러울때 새로이 나타나');
         Print(7,'겠노라고 말하며  홀로 그 동굴에서 살다가 죽');
         Print(7,'었지. 하지만 지금이 그가 말한때라는 걸 그의');
         Print(7,'영혼이 알수있게만 한다면,  그는 다시금 최강');
         Print(7,'의 마법사로 부활해서 당신들을 도와주게 되는');
         Print(7,'사람이지.');
         talk('');
         Print(15,' Spica');
         Print(7,' 지금  초자연력에 대해 알고있고 사용할수 있');
         Print(7,'는 사람은 몇명되지 않는데, 그중의 한 사람이');
         Print(7,'Necromancer 이고 또 지금 말하는 Spica 라네.');
         Print(7,' 자네가 이 기술을 그녀에게 배우지 않는 다면');
         Print(7,'Necromancer 를 만나기 위한 도중에 무릎을 꿇');
         Print(7,'고 말것이며 설령 그와 대결하게 된다 해도 자');
         Print(7,'네들은 참패를 하게 될걸세. 이 기술로 자연을');
         Print(7,'조작하고 인간의 마음을 읽으며 시공간을 넘겨');
         Print(7,'볼수만 있다면  분명 당신은 세계 최강의 전사');
         Print(7,'가 되어있을 걸세.  그리고, 그녀가 있는 곳은');
         Print(7,'바로 물로 덮인 대륙의 Dragon 이 사는 동굴의');
         Print(7,'어느 깊숙한 곳이라네.');
         talk('');
         Print(15,' Ancient Evil');
         Print(7,' 그는 지금, 늪의 대륙의 서쪽 바다 건너 작은');
         Print(7,'섬에 살고 있다네.  그가 사는 섬을 찾기는 무');
         Print(7,'척 어렵겠지만 초자연력으로 공간을 넘겨 보아');
         Print(7,'위치를 파악한후 텔리포트 마법을 통해 이동하');
         Print(7,'면 다다를수 있을 걸세.  그는  당신의 미래를');
         Print(7,'쉽게 풀어주고, 또 새로운 만남을 이어주게 될');
         Print(7,'걸세.');
         talk('');
         Print(7,' 이 외에도 Polaris, Jr.Antares, Lore Hunter');
         Print(7,', Rigel 등등의 사람들을 수도 없이 만나게 되');
         Print(7,'겠지만 반드시 당신에게 도움을 주지만은 않을');
         Print(7,'것이며, 만약 당신이 남을 도와 준다면 반드시');
         Print(7,'그도  당신에게 보이지 않는 도움을 주게 될거');
         Print(7,'라는 말을 끝으로  나는 다시 몇천년의 잠으로');
         Print(7,'빠져들어야 겠네. 그럼 안녕히 ...');
         talk('');
         i := 100 + 20 * x1;
         j := 100 + 20 * y1;
         for k := 1 to 30 do begin
            delay(k*2);
            putimage(i,j,font^[48],CopyPut);
            delay((31-k)*2);
            putimage(i,j,font^[35],CopyPut);
         end;
         map[x+x1,y+y1] := 35;
      end
      else if at(10,18) then begin
         Print(7,' 당신이 유골에 다가서자  어디선가 소리가 들');
         Print(7,'려왔다.');
         PressAnyKey;
         Print(7,' 당신과 나의 만남은 어렇듯 운명적이네. 나는');
         Print(7,'당신이 이때쯤 나를 찾아오리라고 내가 잠들기');
         Print(7,'전 몇 천년 전에 이미 알고 있었다네.');
         Print(7,' 소개하지. 나는 당신의 순회적 운명을 관장하');
         cPrint(7,12,'는 ','시리우스의 의지','라고 하네. 당신은 나를 처');
         Print(7,'음  봤겠지만 나는 원래 당신의 또다른 분신으');
         Print(7,'로서 당신은 결코 나에게는 낯 설지가 않다네.');
         Print(7,'당신은 어느 순간에도 당신이  단지 이 세계에');
         Print(7,'서만 당신의 삶이 존재한다고 생각하는가 ? 분');
         Print(7,'명 지금 현재로서는 그렇게 밖에  생각을 못하');
         Print(7,'지만 실제는 그렇지 않지.  당신은 분명 이 순');
         Print(7,'간에도 다른 공간에서는 또 다른 삶을 살고 있');
         Print(7,'다네. 하지만 ... ''또 다른 삶''이라고 내가 말');
         Print(7,'했지만  결국은 한 운명을 가지고 계속 윤회하');
         Print(7,'는 것일뿐이지.  나는 이렇게 당신이 찾아오는');
         Print(7,'것만도 헤아릴수 없이 겪었지.  언제나 당신은');
         Print(7,'정해진 운명 때문에 어쩔수 없이 나를 계속 찾');
         Print(7,'아오게 되는 거라네.  이해가 가지 않을거라고');
         Print(7,'나도 생각하면서도 달리 설명할 방도가 없어서');
         Print(7,'이런 애매한 말만 되풀이 할 뿐이네.');
         talk('');
         Print(7,' 더 자세한 운명을 알고 싶다면 스왐프 게이트');
         Print(7,'에 있는 피라밋의 예언서를 읽어 보게나. 그러');
         Print(7,'면 더 이해가 빠를걸세.');
         Print(7,' 그래도 잘 이해가 안된다면 ''늪의 대륙''의 외');
         Print(7,'딴 섬에 은둔하고 있는 Draconian을 만나 보도');
         Print(7,'록 하게. 그는 Necromancer가 이전의 공간에서');
         Print(7,'이 공간으로 온 이유를 알고 있기 때문이라네.');
         Print(7,' 그럼 우리의 만남은  다음 공간의 또 다른 운');
         Print(7,'명에 의해 다시 시작될걸세. 그럼 그때까지 안');
         Print(7,'녕히!');
         talk('');
         i := 100 + 20 * x1;
         j := 100 + 20 * y1;
         for k := 1 to 30 do begin
            delay(k*2);
            putimage(i,j,font^[48],CopyPut);
            delay((31-k)*2);
            putimage(i,j,font^[35],CopyPut);
         end;
         map[x+x1,y+y1] := 35;
      end
      else if at(10,30) then begin
         Print(7,' 당신이 유골에 다가서자  어디선가 소리가 들');
         Print(7,'려왔다.');
         PressAnyKey;
         cPrint(7,12,' 나는 이 세계의 운명을 담당하는  ','알비레오의','');
         cPrint(7,12,'','의지','라고 하오. 나는 이 세상이 생기면서 부터');
         Print(7,'늘 이런 모습으로 여기서 지내왔소. 나는 이제');
         Print(7,'껏 세상의 많은 위기들을 보아왔소. 하지만 지');
         Print(7,'금과 같은 공간을 뛰어 넘은 침입자에 의한 위');
         Print(7,'기는 처음이라고 기억되오.  나는 이 곳에서도');
         Print(7,'이 세상 모든것을 볼수있소. 그리고 여태껏 당');
         Print(7,'신의 자라온 모습과 여기에 서 있는 이유도 알');
         Print(7,'고 있소. 또한 Necromancer가 이 세상에 온 이');
         Print(7,'후로 부터의 그의 행동도 보아왔소. 그리고 결');
         Print(7,'국은 ... ... 당신과 그의 미래도 나에게는 보');
         Print(7,'여지고 있소.  나는 이 자리에서  미래의 일을');
         Print(7,'말할수는 없소. 당신이 그 결말을 알고 싶다면');
         Print(7,'''늪의 대륙''에 있는 Draconian 을 만나 보는게');
         Print(7,'좋을거요. 그전에 Ancient Evil도 역시 만나게');
         Print(7,'될것이오. 그리고 한가지를 명심하시오.');
         Print(15,' 당신이 옳다고 생각하는게 항상 옳은 것은 아');
         Print(15,'니오. 남들이 증오하는 것이 항상 당신에게 그');
         Print(15,'릇되게 작용하지는 않을 것이오. 또한, 현재의');
         Print(15,'증오가 미래의 증오가 되지도 않을 것이오. 그');
         Print(15,'리고 결국에는 Necromancer를 용서하시오.');
         talk('');
         i := 100 + 20 * x1;
         j := 100 + 20 * y1;
         for k := 1 to 30 do begin
            delay(k*2);
            putimage(i,j,font^[48],CopyPut);
            delay((31-k)*2);
            putimage(i,j,font^[35],CopyPut);
         end;
         map[x+x1,y+y1] := 35;
      end
      else if at(21,32) then begin
         Print(7,' 당신이 유골에 다가서자  어디선가 소리가 들');
         Print(7,'려왔다.');
         PressAnyKey;
         Print(7,' 안녕하시오. 나는 Necromancer 의 운명을 관장');
         cPrint(7,12,'하고 있는 ','카노푸스의 의지','라고 하오.  이 공간');
         Print(7,'뿐만 아니라 다른 공간에서 존재하고 있는 Nec-');
         Print(7,'romancer의 운명 또한 내가 담당하는 범주에 들');
         Print(7,'어간다오.  하지만 그는 그의 운명을 따르는 존');
         Print(7,'재일뿐 그 이상의 의미는 없소.  그는 수도없는');
         Print(7,'저편의 공간에서 지워진 운명을 다해갔소. 그리');
         Print(7,'고 또 여기서  다시 그의 운명을 시작하려 하고');
         Print(7,'있소. 이 공간 하나 밖에 인식하지 못하는 인간');
         Print(7,'의 사고로는 별 가치가 없는 일이지만,  운명을');
         Print(7,'따르기 위해 다음 공간에서도 같은 운명을 반복');
         Print(7,'해야 한다는 그 금단의 이치는  분명 그도 따르');
         Print(7,'고 싶지 않았을 것이오. 하지만 그는 그 자신도');
         Print(7,'그것이 절대 바뀔수 없는  패러독스라는걸 알고');
         Print(7,'있을게요.  Necromancer 그 자신은 정말 불행한');
         Print(7,'존재라오.  스스로의 운명을 등에 지고  힘겹게');
         Print(7,'차원을 쫓기어 다니는 힘없는 짐승일 뿐이오.');
         Print(7,' 당신이  마지막의 그에게  받을수 있는 느낌은');
         Print(7,'진정한 마음에서 우러나오는 동정일것이오.  당');
         Print(7,'신은  저번 공간에서도 역시 그것을 느꼈소. 하');
         Print(7,'지만 그때의 기억은  당신이 이 세계에 그를 물');
         Print(7,'리치려는 운명을 지니고 다시 태어났을때  이미');
         Print(7,'사라져 버렸소. 당신은 내말을 이해하지 못하겠');
         Print(7,'지만 그것은 사실이오.  지금은  그를 증오로서');
         Print(7,'맞이하려 하겠지만 그 증오는 다시 다음 공간으');
         Print(7,'로 이어지려하오.  당신이 그를 물리 친다고 하');
         Print(7,'여도 다시 다음 공간에서도 지금과 같은 대립을');
         Print(7,'반복할 뿐이오.  당신과 그와의 대립은 이 우주');
         Print(7,'가 생기기 시작할때 부터 지금까지 수도없이 반');
         Print(7,'복했고 그 이후로도 이 우주가 사라질때까지 영');
         Print(7,'원히 반복될 것이오.  그리고  마지막으로 내가');
         Print(7,'하고 싶은 말은 이런것이오.');
         Print(15,' 당신은 결국 Necromancer를 동정 할지 모르오.');
         Print(15,'하지만 결코 그만이 동정의 대상이 아니오.  결');
         Print(15,'국은  그와 연관되어 운명이 결정지워진 당신도');
         Print(15,'예외가 될수는 없소.');
         talk('');
         i := 100 + 20 * x1;
         j := 100 + 20 * y1;
         for k := 1 to 30 do begin
            delay(k*2);
            putimage(i,j,font^[48],CopyPut);
            delay((31-k)*2);
            putimage(i,j,font^[35],CopyPut);
         end;
         map[x+x1,y+y1] := 35;
      end
      else if at(21,22) then begin
         Print(7,' 당신이 유골에 다가서자  어디선가 소리가 들');
         Print(7,'려왔다.');
         PressAnyKey;
         Print(7,' 당신 앞의 유골은 바로 나의것이오. 나를 소개');
         cPrint(7,12,'하자면 ','아크투루스의 의지','라고 불리우는 존재로');
         Print(7,'서 Ancient Evil의 운명을 관장하고 있소. 이름');
         Print(7,'에서 알수있듯이  그를 수호하는 의지는 목자의');
         Print(7,'성격을 갖고있소. 하지만 그의 이름이나 평판으');
         Print(7,'로 볼때는  전혀 그런 성격을 알지 못하게 되고');
         Print(7,'마는게 보통이오. 그는 Lord Ahn과 대립하는 운');
         Print(7,'명을 지니고 세상에 존재하게 되었소.  마치 당');
         Print(7,'신과 Necromancer와 같이 말이오. Lord Ahn과의');
         Print(7,'대립 관계란 운명 때문에  그는 그의 모든 성격');
         Print(7,'을 포기한채 Lord Ahn을 위하여 악의 편에 서게');
         Print(7,'되었던 것이오. 그때, 둘중에 누구 하나가 악의');
         Print(7,'대표가 되지 않으면 안되었고  Lord Ahn은 결코');
         Print(7,'세인의 지탄을 받는 악을 대표하려고 하지 않음');
         Print(7,'으로 해서  그가 직접 악의 대표가 되기로 하였');
